MG.RouteL.ruRU = function() return {
  stations = {
    ["01-1"] = {name="Долина Испытаний", tips={{k="交通", text="Выходец из другой стартовой зоны? Следуйте по дороге на юг через Дуротар. Войдите в Долина Испытаний с востока и найдите Калтунк. См. путевые заметки выше."}, {k="取捨", text="Выполните квесты «Wayward Weapons», Ленивые батраки и оба Грот Пылающего Клинка. Сгруппируйте цели в два цикла."}, {k="取捨", text="Завершите квест Бес (Злобные фамильяры или Злобные фамильяры), затем примите Медальон Пылающего Клинка от Зурита Востроглазая. Только чернокнижники.", s={{"Завершите квест Бес (Злобные фамильяры или Злобные фамильяры), затем примите Медальон Пылающего Клинка от Зурита Востроглазая. Только чернокнижники.", {class={"WARLOCK"}}}}}, {k="提醒", text="Ниже 6 уровня? Убейте Пятнистый вепрь, Рабочий скорпид или Злобный фамилиар на пути к Деревня Сен'джин.", s={{"Ниже 6 уровня?"}, {"Убейте Пятнистый вепрь, Рабочий скорпид или Злобный фамилиар на пути к Деревня Сен'джин"}}}}, danger={[1]="Изгиб Грот Пылающего Клинка может вытащить несколько бесов одновременно. Очистите вход, прежде чем брать кирку, и держите выход свободным."}, grind={[1]={mob="Пятнистый вепрь", note="Плотные, в основном нейтральные обычные мобы. Оттягивайте по одному врагу к северу от Долина Испытаний к Кабаньи клыки на уровнях 1-2."}, [2]={mob="Рабочий скорпид", note="Плотные, в основном нейтральные обычные мобы. Оттягивайте по одному врагу к северо-западу от Логова, выполняя Жала скорпидов."}, [3]={mob="Злобный фамилиар", note="Много обычных противников у Грота Пылающего Клинка. Сначала выманивайте их снаружи по одному. Достигните 6-го уровня перед выходом из долины."}}, supply={[1]={npc="Рарк"}, [2]={npc="Зляк"}, [3]={npc="Дуокна"}}, steps={[1]={npc="Калтунк", tgt="Калтунк"}, [2]={hint="Поговорите с Горнеком. Вы помните, как Калтунк отметил на карте его местонахождение и упомянул, что Горнек живет в Логове, здании, расположенном на западе."}, [3]={npc="Горнек", tgt="Горнек"}, [4]={npc="Подарочный сертификат долины Испытаний", npcObj=true, tag="Необязательно, Требуется внутриигровая проверка", desc="Принимайте, только если у вас есть Подарочный сертификат долины Испытаний. Щелкните правой кнопкой мыши стартовый ваучер вашей расы. На карте нет самовывоза."}, [5]={hint="Передайте подарочный сертификат долины Испытаний Магге.", tag="Необязательно", desc="Принимайте, только если у вас есть Подарочный сертификат долины Испытаний."}, [6]={npc="Магга", tgt="Магга", tag="Необязательно", desc="Принимайте, только если у вас есть Подарочный сертификат долины Испытаний."}, [7]={npc="Горнек", tgt="Горнек"}, [8]={npc="Горнек", tgt="Горнек"}, [9]={hint="Убейте 10 пятнистых вепрей и вернитесь в Логово к Горнеку."}, [10]={hint="Добудьте 6 |4комплект:комплекта:комплектов; брошенного тренировочного оружия и вернитесь к Кзану Шипорубу в Логово."}, [11]={npc="Горнек", tgt="Горнек"}, [12]={npc="Кзан Шипоруб", tgt="Кзан Шипоруб"}, [13]={npc="Горнек", tgt="Горнек"}, [14]={npc="Галгар", tgt="Галгар"}, [15]={npc="Штейгер Тазз'рил", tgt="Штейгер Тазз'рил"}, [16]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [17]={text="Очистите начальную долину, затем идите к пещере на севере."}, [18]={hint="Добудьте 10 хвостов рабочих скорпидов и принесите их в Логово Горнеку.", desc="Частота выпадения: Рабочий скорпид в Долина Испытаний, согласно Wowhead."}, [19]={hint="Принесите Галгару 10 плодов кактуса."}, [20]={hint="Проучите ленивых батраков дубинкой старшины. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз'рилу в долине Испытаний.", desc="Используйте дубинку бригадира, чтобы разбудить пятерых спящих пеонов."}, [21]={hint="Убейте 12 злобных фамильяров и вернитесь к Зурите Востроглазой, которая ждет вас у Логова.", desc="Чернокнижники: проведите своего беса через классовый квест Рузан."}, [22]={npc="Хана'зуа", tgt="Хана'зуа", tag="Необязательно"}, [23]={hint="Убейте Саркота и принесите его коготь Хана'зуа.", tag="Необязательно"}, [24]={npc="Хана'зуа", tgt="Хана'зуа", tag="Необязательно"}, [25]={npc="Хана'зуа", tgt="Хана'зуа", tag="Необязательно"}, [26]={hint="Расскажите Горнеку о том, что Хана'зуа в беде.", tag="Необязательно"}, [27]={npc="Горнек", tgt="Горнек", tag="Необязательно"}, [28]={npc="Горнек", tgt="Горнек"}, [29]={npc="Галгар", tgt="Галгар"}, [30]={npc="Штейгер Тазз'рил", tgt="Штейгер Тазз'рил"}, [31]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [32]={npc="Штейгер Тазз'рил", tgt="Штейгер Тазз'рил"}, [33]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [34]={hint="Принесите штейгеру Тазз'рилу его кирку.", desc="Получите кирку в Грот Пылающего Клинка в той же поездке, что и медальон."}, [35]={hint="Принесите медальон Пылающего Клинка Зурите Востроглазой, стоящей у Логова.", desc="Найдите Йоррог Тень Проклятия в пещере и заберите Медальон Пылающего Клинка."}, [36]={npc="Штейгер Тазз'рил", tgt="Штейгер Тазз'рил"}, [37]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [38]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [39]={npc="Потерянный дневник", npcObj=true, tag="Необязательно", desc="Найдите Потерянный дневник рядом с Зурита Востроглазая."}, [40]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [41]={hint="Прочтите пергамент и поговорите с Франгом в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [42]={npc="Франг", tgt="Франг", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [43]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [44]={hint="Прочтите простую табличку и поговорите с Франгом в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [45]={npc="Франг", tgt="Франг", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [46]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [47]={hint="Прочтите исписанный пергамент и поговорите с Руагом в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [48]={npc="Руаг", tgt="Руаг", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [49]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [50]={hint="Прочтите табличку с письменами и поговорите с Руагом в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [51]={npc="Руаг", tgt="Руаг", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [52]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [53]={hint="Прочтите рунический пергамент и поговорите с Шикрик в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [54]={npc="Шикрик", tgt="Шикрик", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [55]={npc="Горнек", tgt="Горнек", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [56]={hint="Поговорите с Шикрик в долине Испытаний.", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [57]={npc="Шикрик", tgt="Шикрик", desc="Выполните Кабаньи клыки, затем возьмите вводное задание у учителя своего класса."}, [58]={npc="Канага заклинатель земли", tgt="Канага заклинатель земли"}, [59]={hint="Принесите Канаге заклинателю земли 2 копыта ловцов Скверны."}, [60]={npc="Канага заклинатель земли", tgt="Канага заклинатель земли"}, [61]={npc="Канага заклинатель земли", tgt="Канага заклинатель земли", desc="Выпейте Сапту, чтобы увидеть Низшее воплощение земли."}, [62]={hint="Найдите Священный Камень и выпейте рядом с ним сапту Земли.", desc="Выпейте Сапту, чтобы увидеть Низшее воплощение земли."}, [63]={npc="Низшее воплощение земли", tgt="Низшее воплощение земли", desc="Выпейте Сапту, чтобы увидеть Низшее воплощение земли."}, [64]={npc="Низшее воплощение земли", tgt="Низшее воплощение земли", desc="Завершите квест, чтобы получить Тотем земли."}, [65]={hint="Отнесите необработанный кварц Канаге заклинателю земли в долину Испытаний.", desc="Завершите квест, чтобы получить Тотем земли."}, [66]={npc="Канага заклинатель земли", tgt="Канага заклинатель земли", desc="Завершите квест, чтобы получить Тотем земли."}, [67]={npc="Горнек", tgt="Горнек"}, [68]={hint="Прочтите пергамент с письменами и поговорите с Джен'шан в долине Испытаний."}, [69]={npc="Джен'шан", tgt="Джен'шан"}, [70]={npc="Горнек", tgt="Горнек"}, [71]={hint="Поговорите с Джен'шан в долине Испытаний."}, [72]={npc="Джен'шан", tgt="Джен'шан"}, [73]={npc="Горнек", tgt="Горнек"}, [74]={hint="Прочтите гниющий пергамент и поговорите с Нартоком в Логове в долине Испытаний."}, [75]={npc="Нарток", tgt="Нарток"}, [76]={npc="Горнек", tgt="Горнек"}, [77]={hint="Прочтите, что написано на оскверненной скрижали, и поговорите с Нартоком в Логове в Долине Испытаний."}, [78]={npc="Нарток", tgt="Нарток"}, [79]={npc="Рузан", tgt="Рузан", desc="Пропустите этот маршрут Долина Испытаний, если вы разблокировали своего чертенка в Могильник."}, [80]={hint="Принесите Рузану 6 голов злобных фамильяров.", desc="Пропустите этот маршрут Долина Испытаний, если вы разблокировали своего чертенка в Могильник."}, [81]={npc="Рузан", tgt="Рузан", desc="Пропустите этот маршрут Долина Испытаний, если вы разблокировали своего чертенка в Могильник."}, [82]={npc="Рузан", tgt="Рузан"}, [83]={hint="Поговорите с Зуритой Востроглазой."}, [84]={npc="Зурита Востроглазая", tgt="Зурита Востроглазая"}, [85]={npc="Горнек", tgt="Горнек", desc="Сдайте Кабаньи клыки, чтобы получить планшет."}, [86]={hint="Прочтите освященную табличку и поговорите с Кен'джаем у Логова в долине Испытаний.", desc="Сдайте Кабаньи клыки, чтобы получить планшет."}, [87]={npc="Кен'джай", tgt="Кен'джай", desc="Сдайте Кабаньи клыки, чтобы получить планшет."}, [88]={npc="Кен'джай", tgt="Кен'джай"}, [89]={hint="Поговорите с Тай'джин в Дуротаре."}, [90]={npc="Тай'джин", tgt="Тай'джин"}, [91]={npc="Горнек", tgt="Горнек", desc="Сдайте Кабаньи клыки, затем посмотрите трейнер Маг."}, [92]={hint="Прочтите покрытый письменами пергамент и поговорите с Май'ах у входа в Логово в долине Испытаний.", desc="Сдайте Кабаньи клыки, затем посмотрите трейнер Маг."}, [93]={npc="Май'ах", tgt="Май'ах", desc="Сдайте Кабаньи клыки, затем посмотрите трейнер Маг."}, [94]={npc="Горнек", tgt="Горнек", desc="Сдайте Кабаньи клыки, затем посмотрите трейнер Маг."}, [95]={hint="Прочтите табличку с тайными знаками и поговорите с Май'ах у входа в Логово в долине Испытаний.", desc="Сдайте Кабаньи клыки, затем посмотрите трейнер Маг."}, [96]={npc="Май'ах", tgt="Май'ах", desc="Сдайте Кабаньи клыки, затем посмотрите трейнер Маг."}, [97]={text="Покиньте Долина Испытаний и следуйте по дороге на Деревня Сен'джин."}}},
    ["01-2"] = {name="Дуротар", nameA="Дуротар: {a:367} & {a:362}", shortA="Дуротар: {a:367} +", tips={{k="取捨", text="Сделайте Больше сумок - больше добычи!. Соберите Лоскуты холста вместе с другими целями Крепость Тирагард."}, {k="取捨", text="Сдайте Бей предателей!, чтобы разблокировать Обломки кораблекрушения. Сделайте это вместе с Растворитель."}, {k="取捨", text="Сохраните цепочку подземелий Расселина Теней. Если вы планируете запускать Огненная пропасть, возьмите Тайные враги ( → →) из Тралл. Получите значок в лагере Пылающий Клинок на севере."}, {k="提醒", text="Ниже 12 уровня? Выполните Обеспечение безопасного сообщения, Скала Черепа или первые несколько квестов Угроза из «Внизу».", s={{"Ниже 12 уровня?"}, {"Выполните Обеспечение безопасного сообщения, Скала Черепа или первые несколько квестов Угроза из «Внизу»"}}}}, danger={[1]="Лестницы и дверные проемы в Крепость Тирагард могут вытягивать моряков наверх. Сначала очистите внешнюю стену и вход.", [2]="Морские гиганты бродят по территории наг на северном берегу. Убейте ближайших мобов, прежде чем вытащить одного. Отступите вдоль берега, если попадете в беду."}, grind={[1]={mob="Страж бухты Кул-Тираса", note="Плотные нормальные мобы на Крепость Тирагард. Выйдите на улицу, чтобы избежать добавления в коридорах. Соберите Лоскуты холста для новой сумки."}, [2]={mob="Боевой страж племени Иглогривых", note="Обычные мобы собираются к западу от Колючий Холм. Двигайтесь по краю лагеря и наблюдайте за патрулями. Сопряжение с Вторжение."}, [3]={mob="Грозовая ведьма из стаи Пыльного Ветра", note="Обычная группа мобов на севере Дуротар. Используйте крышку, чтобы приблизить ролики. Сделайте Обеспечение безопасного сообщения или измельчите до 12 перед Оргриммар."}}, supply={[1]={npc="Трайексир"}, [2]={npc="Хозяин таверны Гроск"}, [3]={npc="Вьярк"}, [4]={npc="Хозяин таверны Гроск"}, [5]={npc="Грахт"}, [6]={npc="Дорас"}}, steps={[1]={npc="Укор", tgt="Укор", desc="Ищите Укор на дороге от Долина Испытаний до Деревня Сен'джин."}, [2]={hint="Поговорите с мастером Гадрином в деревне Сен'джин."}, [3]={npc="Мастер Гадрин", tgt="Мастер Гадрин"}, [4]={npc="Лар Ночной Клык", tgt="Лар Ночной Клык"}, [5]={npc="Вель'рин Клык", tgt="Вель'рин Клык"}, [6]={npc="Мастер Ворнал", tgt="Мастер Ворнал"}, [7]={npc="Мастер Гадрин", tgt="Мастер Гадрин"}, [8]={npc="Мастер Гадрин", tgt="Мастер Гадрин"}, [9]={npc="Мастер Гадрин", tgt="Мастер Гадрин"}, [10]={npc="Вель'рин Клык", tgt="Вель'рин Клык"}, [11]={npc="Ксар'Ти", tgt="Ксар'Ти"}, [12]={npc="Мастер Ворнал", tgt="Мастер Ворнал"}, [13]={npc="Па'зула", tgt="Па'зула", tag="Необязательно", desc="Делайте это только в том случае, если вам удастся добыть распыляющие материалы."}, [14]={text="Сначала зарегистрируйтесь в Колючий Холм."}, [15]={hint="Убейте 6 темногорных ползунов и 6 темногорных скрытней в южном Дуротаре и сообщите об этом Га'Току в Колючем Холме."}, [16]={hint="Отнесите дневник Бракку к Колючему Холму.", tag="Необязательно"}, [17]={npc="Бракк", tgt="Бракк", tag="Необязательно"}, [18]={npc="Бракк", tgt="Бракк", tag="Необязательно"}, [19]={hint="Сядьте у костра Бракка и дождитесь получения усиления \"Улучшенный отдых\".", tag="Необязательно"}, [20]={npc="Бракк", tgt="Бракк", tag="Необязательно"}, [21]={npc="Бракк", tgt="Бракк", tag="Необязательно"}, [22]={npc="Бракк", tgt="Бракк", tag="Необязательно", desc="Сначала изучите Снятие шкур. Сдайте по адресу Оргриммар."}, [23]={hint="Поговорите с Оргнилом Душегрызом на Колючем Холме."}, [24]={hint="Отнесите сумку Укора хозяину таверны Гроску в Колючий Холм."}, [25]={npc="Оргнил Душегрыз", tgt="Оргнил Душегрыз"}, [26]={npc="Га'Ток", tgt="Га'Ток"}, [27]={npc="Хозяин таверны Гроск", tgt="Хозяин таверны Гроск"}, [28]={text="В Колючий Холм свяжите свой камень возвращения с Хозяин таверны Гроск (51.51, 41.64)."}, [29]={npc="Га'Ток", tgt="Га'Ток"}, [30]={npc="Оргнил Душегрыз", tgt="Оргнил Душегрыз"}, [31]={npc="Повар Торка", tgt="Повар Торка"}, [32]={npc="Га'Ток", tgt="Га'Ток"}, [33]={npc="Фурл Хмурый Лоб", tgt="Фурл Хмурый Лоб", star={"Кожаная сумка ручной работы"}}, [34]={npc="Туррок", tgt="Туррок"}, [35]={npc="Повар Торка", tgt="Повар Торка"}, [36]={hint="Поговорите с поваром Торкой в Колючем Холме, чтобы стать поваром.", tag="Необязательно"}, [37]={npc="Повар Торка", tgt="Повар Торка", tag="Необязательно"}, [38]={text="Крепость Тирагард → затонувшие корабли → Утес Колкара и Острова Эха"}, [39]={hint="Убейте 10 моряков Кул-Тираса, 8 стражей бухты Кул-Тираса и лейтенанта Бенедикта и возвращайтесь к Га'Току на Колючий Холм."}, [40]={hint="Принесите 8 лоскутов холста Фурлу Хмурому Лбу, стоящему на сторожевой башне рядом с Колючим Холмом."}, [41]={hint="Добудьте разбойничий боевой топор, разбойничий лук и разбойничий щит на задворках крепости Тирагард, а затем принесите их Турроку в Колючий Холм."}, [42]={npc="Старый конверт", npcObj=true, desc="Получите ключ Лейтенант Бенедикт. Откройте сундук наверху и возьмите Старый конверт."}, [43]={npc="Потерянная сума Укора", npcObj=true, tag="Необязательно", desc="Если вы соберете рюкзак по пути, начните квест и направляйтесь на юг, в Укор."}, [44]={text="Вернитесь к Колючий Холм из Крепость Тирагард. Подожгите, если готово."}, [45]={hint="Отнесите приказы адмирала Праудмура Га'току на Колючий Холм."}, [46]={npc="Га'Ток", tgt="Га'Ток"}, [47]={npc="Га'Ток", tgt="Га'Ток"}, [48]={npc="Туррок", tgt="Туррок", desc="Рубака Колючего Холма также предлагает этот квест (53.06, 42.48)."}, [49]={npc="Фурл Хмурый Лоб", tgt="Фурл Хмурый Лоб", star={"Кожаная сумка ручной работы"}}, [50]={npc="Га'Ток", tgt="Га'Ток"}, [51]={npc="Га'Ток", tgt="Га'Ток", tag="Необязательно"}, [52]={hint="Принесите 4 невредимых глаза макрур и 8 фиалов со слизью крабов мастеру Ворналу в деревне Сен'джин."}, [53]={hint="Га'Ток с Колючего Холма просит вас принести ему 3 комплекта инструментов гномов, найти которые можно в обломках кораблей у побережья."}, [54]={hint="Верните сумку Укору в южном Дуротаре.", tag="Необязательно"}, [55]={npc="Укор", tgt="Укор", tag="Необязательно"}, [56]={npc="Мастер Ворнал", tgt="Мастер Ворнал"}, [57]={hint="Лар Ночной Клык из деревни Сен'джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что в Утесе Колкара."}, [58]={npc="Пал'джу", tgt="Пал'джу", tag="Необязательно", desc="Найдите Пал'джу по адресу Утес Колкара. Очистите дорогу, прежде чем начинать сопровождение."}, [59]={hint="Помогите Пал'джу выбраться с утеса Колкара и сообщите об этом мастеру Ворналу в деревне Сен'джин.", tag="Необязательно", desc="Найдите Пал'джу по адресу Утес Колкара. Очистите дорогу, прежде чем начинать сопровождение."}, [60]={npc="Мастер Ворнал", tgt="Мастер Ворнал", tag="Необязательно", desc="Найдите Пал'джу по адресу Утес Колкара. Очистите дорогу, прежде чем начинать сопровождение."}, [61]={npc="Лар Ночной Клык", tgt="Лар Ночной Клык"}, [62]={hint="Принесите 3 яйца кнутохвостов повару Торке в Колючий Холм."}, [63]={hint="Принесите 4 шкуры дуротарских тигров Вель'рину Клыку в деревне Сен'джин."}, [64]={hint="Украдите череп Миншины из магического круга на островах Эха."}, [65]={hint="Убейте Залазана, убейте 8 троллей-вудуистов и 8 проклятых троллей."}, [66]={hint="Добудьте 8 |4забытого идола:забытых идолов:забытых идолов; лоа на островах Эха и принесите их мастеру Гадрину в деревню Сен'джин."}, [67]={hint="Принесите яйца кровопалого матриарха Ксар'Ти в деревню Сен'джин."}, [68]={hint="Добудьте 3 порции светящегося осадка для Па'зулы из деревни Сен'джин. Светящийся осадок можно получить, распылив проклятые подвески, добытые у троллей на островах Эха.", tag="Необязательно", desc="Кулон Сглаз можно найти здесь. Получите Светящийся осадок путем распыления чар."}, [69]={npc="Вель'рин Клык", tgt="Вель'рин Клык"}, [70]={npc="Мастер Гадрин", tgt="Мастер Гадрин"}, [71]={npc="Мастер Гадрин", tgt="Мастер Гадрин"}, [72]={npc="Мастер Гадрин", tgt="Мастер Гадрин"}, [73]={npc="Ксар'Ти", tgt="Ксар'Ти"}, [74]={npc="Па'зула", tgt="Па'зула", tag="Необязательно"}, [75]={text="Используйте свой камень возвращения, чтобы в