    ["05-d29"] = {name="Забытый Город: Запад", entrance="Фералас (1444), 60.30, 30.20. Портал на западной стороне двора.", pickup="Посетите Ведун Королуск в Лагерь Мохаче и возьмите Эльфийские легенды на уровне 54. Летите в лагерь и следуйте по главной дороге на запад. Проверьте, есть ли у кого-нибудь Серповидный ключ, или сначала запустите восточное крыло.", pickupS={{"Посетите Ведун Королуск в Лагерь Мохаче и возьмите Эльфийские легенды на уровне 54"}, {"Летите в лагерь и следуйте по главной дороге на запад"}, {"Проверьте, есть ли у кого-нибудь Серповидный ключ, или сначала запустите восточное крыло"}}, tips={{k="動線", text="Западные ворота → очистите садовые пилоны → Тендрис Криводрев → увидите Древнего наверху и очистите оставшиеся пилоны, при необходимости Календрис и Иллианну → Бессмер'тер в тюрьме → Принц Тортелдрин в Библиотека. Повернитесь к Древнему, затем вернитесь к Библиотека за сундуком и останками."}, {k="取捨", text="Выполните Эльфийские легенды, Древнее безумие и Сокровище Шен'дралар за один проход. Сохраните материалы для чар и более длинные цепочки из нескольких подземелий для прохождения снаряжения."}, {k="說明", text="Подземелье для пяти игроков. Получите Серповидный ключ у Пузиллин в восточном крыле. Очистите все пять пилонов перед Бессмер'тер. См. примечания к учебникам библиотеки в северном крыле.", s={{"Подземелье для пяти игроков"}, {"Получите Серповидный ключ у Пузиллин в восточном крыле"}, {"Очистите все пять пилонов перед Бессмер'тер"}, {"См. примечания к учебникам библиотеки в северном крыле"}}}, {k="提醒", text="Подземелье для пяти игроков. Получите Серповидный ключ у Пузиллин в восточном крыле. Очистите все пять пилонов перед Бессмер'тер. См. примечания к учебникам библиотеки в северном крыле.", s={{"Подземелье для пяти игроков"}, {"Получите Серповидный ключ у Пузиллин в восточном крыле"}, {"Очистите все пять пилонов перед Бессмер'тер"}, {"См. примечания к учебникам библиотеки в северном крыле"}}}}, steps={[1]={npc="Ведун Королуск", tgt="Ведун Королуск", desc="Заберите в Лагерь Мохаче. Доберитесь до Библиотека по короткому пути на запад или север."}, [2]={text="Вход: Забытый Город: Запад"}, [3]={npc="Прародительница Шен'дралар", tgt="Прародительница Шен'дралар", tag="Требуется внутриигровая проверка", desc="Сначала поговорите с Прародительница Шен'дралар на верхнем уровне Забытый Город West."}, [4]={hint="Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.", desc="Сначала очистите все пять пилонов. Карта: Бессмер'тер (35.00,57.60), Принц (62.20,22.70). Место: Очистите пять пилонов, затем пройдите через запертую дверь к Бессмер'тер и Принцу. Порядок: Пять пилонов → Бессмер'тер → принц в библиотеке.", spot="Очистите пять пилонов, затем пройдите через запертую дверь к Бессмер'тер и Принцу."}, [5]={npc="Прародительница Шен'дралар", tgt="Прародительница Шен'дралар", tag="Требуется внутриигровая проверка", spot="Библиотека: древний Шен'дралар"}, [6]={npc="Прародительница Шен'дралар", tgt="Прародительница Шен'дралар", tag="Требуется внутриигровая проверка", desc="Сдайтесь Древнему, затем примите продолжение. Сделайте это на той же трассе, что и Древнее безумие.", preText="Древнее безумие"}, [7]={hint="Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!", desc="Место: Перейдите от клетки Бессмер'тер к Библиотека. Проверьте под лестницей сундук.", spot="Перейдите от клетки Бессмер'тер к Библиотека. Проверьте под лестницей сундук."}, [8]={npc="Сокровище Шен'дралар", npcObj=true, tag="Требуется внутриигровая проверка", spot="Сундук Шен'дралар под лестницей библиотеки"}, [9]={hint="Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.", desc="Место: Следуйте по коридору от клетки до Библиотека. Ищите останки у полок.", spot="Следуйте по коридору от клетки до Библиотека. Ищите останки у полок."}, [10]={npc="Ведун Королуск", tgt="Ведун Королуск"}}},
    ["05-d28"] = {name="Забытый Город: Восток", entrance="Фералас (1444), 64.80, 30.20. Портал в углублении вдоль восточной стены арены.", pickup="На уровне 54 возьмите из Военный глашатай Горлач при прохождении через Оргриммар на ветке Храбростан. Свернитесь к Тало и возьмите Сеть Лефтендрис по адресу Лагерь Мохаче. Летите в Лагерь Мохаче и посетите Аж'Тордин в Павильон Лорисс. Для Реликварий Чистоты возьмите его в Лунная поляна, соберите реликварий в Деревня Южного Ветра и сдайте его в Ночная Гавань, чтобы разблокировать Осколки сквернита. Сохраните эту цепочку для последующего запуска, если потребуется.", pickupS={{"На уровне 54 возьмите из Военный глашатай Горлач при прохождении через Оргриммар на ветке Храбростан"}, {"Свернитесь к Тало и возьмите Сеть Лефтендрис по адресу Лагерь Мохаче"}, {"Летите в Лагерь Мохаче и посетите Аж'Тордин в Павильон Лорисс"}, {"Для Реликварий Чистоты возьмите его в Лунная поляна, соберите реликварий в Деревня Южного Ветра и сдайте его в Ночная Гавань, чтобы разблокировать Осколки сквернита"}, {"Сохраните эту цепочку для последующего запуска, если потребуется"}}, tips={{k="動線", text="Преследуйте Пузиллин от входа и сразитесь с ним в конце → Лефтендрис и Гидротварь на боковых тропинках → Зеврим Терновое Копыто у алтаря сатиров → Алззин Перевертень. Введите Библиотека с запада или севера."}, {k="取捨", text="Получите Серповидный ключ в Забытый Город East. Квесты Тало и Пузиллин соединяются быстрее всего. Если Осколки сквернита все еще заблокирован, не пересекайте две зоны ради реликвария."}, {k="說明", text="Подземелье для пяти игроков. Используйте восточный вход. Не пропускайте Пузиллин при прохождении босса. Сохраните ключ от западного и северного крыльев.", s={{"Подземелье для пяти игроков"}, {"Используйте восточный вход"}, {"Не пропускайте Пузиллин при прохождении босса"}, {"Сохраните ключ от западного и северного крыльев"}}}, {k="提醒", text="Подземелье для пяти игроков. Используйте восточный вход. Не пропускайте Пузиллин при прохождении босса. Сохраните ключ от западного и северного крыльев.", s={{"Подземелье для пяти игроков"}, {"Используйте восточный вход"}, {"Не пропускайте Пузиллин при прохождении босса"}, {"Сохраните ключ от западного и северного крыльев"}}}}, steps={[1]={npc="Военный глашатай Горлач", tgt="Военный глашатай Горлач", desc="Пропустите городскую вводное задание, взяв Сеть Лефтендрис прямо у Thalo."}, [2]={hint="Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе."}, [3]={npc="Тало Терновое Копыто", tgt="Тало Терновое Копыто"}, [4]={npc="Тало Терновое Копыто", tgt="Тало Терновое Копыто", desc="Орда квест. Ввод Лагерь Мохаче не является обязательным."}, [5]={npc="Аж'Тордин", tgt="Аж'Тордин", desc="Найдите Павильон Лорисс к северу от Лагерь Мохаче."}, [6]={npc="Рабин Сатурна", tgt="Рабин Сатурна", desc="Уже на основном маршруте на остановках 52, 56 и 59. Если сдали, пропускайте."}, [7]={hint="Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне."}, [8]={npc="Рабин Сатурна", tgt="Рабин Сатурна"}, [9]={npc="Рабин Сатурна", tgt="Рабин Сатурна", desc="Принесите Реликварий Чистоты. Если не выполнено, сохраните его для следующего запуска.", preText="Реликварий Чистоты"}, [10]={text="Вход: Забытый Город: Восток"}, [11]={hint="Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.", desc="Карта: встретите Пузиллин на 74.40, 44.00. Разговаривайте с ним на каждой остановке, чтобы преследовать его. Место: Поговорите с Пузиллин у восточного входа и преследуйте его до конца. Порядок: Поговорите с ними на каждой остановке, чтобы начать бой.", spot="Поговорите с Пузиллин у восточного входа и преследуйте его до конца."}, [12]={hint="Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.", desc="Карта DungeonsForever: Лефтендрис (44.00, 47.40). Место: Пройдите по верхнему проходу из сада на платформу Лефтендрис.", spot="Пройдите по верхнему проходу из сада на платформу Лефтендрис."}, [13]={hint="Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне.", desc="Карта: Альззин (56.40, 28.10). Осколок сквернита находится неподалеку. Место: Следуйте по последнему туннелю в Альззин. Убейте его, затем обыщите и запечатайте осколок.", spot="Следуйте по последнему туннелю в Альззин. Убейте его, затем обыщите и запечатайте осколок."}, [14]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Требуется внутриигровая проверка", desc="На 60-м уровне заберите у Лидроса в Библиотека на западном или северном пути, затем идите на восток."}, [15]={hint="Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.", desc="Карта DungeonsForever: Гидротварь (56.50, 68.50). Место: Сверните по нижнему водному пути на Забытый Город East. Убейте Гидротварь у бассейна.", spot="Сверните по нижнему водному пути на Забытый Город East. Убейте Гидротварь у бассейна."}, [16]={npc="Аж'Тордин", tgt="Аж'Тордин"}, [17]={npc="Тало Терновое Копыто", tgt="Тало Терновое Копыто"}, [18]={npc="Рабин Сатурна", tgt="Рабин Сатурна"}, [19]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Требуется внутриигровая проверка", desc="Вернитесь в Библиотека и сдайте его, чтобы узнать высший ранг Сотворение воды."}}},
    ["04-55"] = {name="Кратер Ун'Горо", tips={{k="交通", text="Пройдите через Прибамбасск на шагах 1 и 11 и по пути используйте Механический йети. На последнем этапе сверните на северо-западный склон в сторону Силитус."}, {k="取捨", text="Сдайте Новые источники в Источники Ледяного Пламени и Йети где-то рядом… в Круговзор. Сохраните Память Линкена для Железнолесье."}, {k="取捨", text="Используйте Супер Яйц-О-Матик, только если вы взяли яйцо и все еще можете его сдать. В противном случае не отступайте."}, {k="提醒", text="Эта нога по-прежнему предназначена для уровней 57-59. Если вы позади на опыт, убейте обычных элементалей на Вулкан Огненного Венца или горилл на севере. Следите за дьяволозаврами на равнинах.", s={{"Эта нога по-прежнему предназначена для уровней 57-59"}, {"Если вы позади на опыт, убейте обычных элементалей на Вулкан Огненного Венца или горилл на севере"}, {"Следите за дьяволозаврами на равнинах"}}}}, danger={[1]="Элитные дьяволозавры 54-56 уровней патрулируют равнины к югу от Вулкан Огненного Венца. Прежде чем сопровождать Ринго, разведайте маршрут и держитесь склона."}, grind={[1]={mob="Живое пламя", note="Обычные элементали более высокого уровня в Вулкан Огненного Венца. Сочетайте с квестом на вулкан. Двигайтесь по склону и избегайте патрулей дьяволозавров на равнине."}, [2]={mob="Смоляной господин", note="Обычные смоляные мобы возле Укрытие Маршалла. Пройдите несколько кругов до последнего участка опыт. Вытаскивайте по одному врагу с края бассейна."}}, supply={[1]={npc="Грайф"}, [2]={npc="Таратор"}, [3]={npc="Нергал"}, [4]={npc="Нергал"}, [5]={npc="Хозяин таверны Ворчунелло"}}, steps={[1]={text="Сначала завершите квесты на кладбище в Прибамбасск. Если вы выполняете квест Механический йети, используйте его в городе, прежде чем идти по южной дороге."}, [2]={npc="Яйц-О-Матик", npcObj=true, tag="Необязательно", desc="Используйте яйцо из Высокогорье Блеклых Перьев в Фералас. Пропустите, если это уже сделано."}, [3]={hint="Использовать/собрать: Яйцо гиппогрифа", tag="Необязательно"}, [4]={npc="Яйц-О-Матик", npcObj=true, tag="Необязательно"}, [5]={hint="Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана.", desc="Выпивание это тебя убивает. Поговорите, пока мертвы, а затем воскресните на кладбище."}, [6]={npc="Гаэриан", tgt="Гаэриан"}, [7]={npc="Гаэриан", tgt="Гаэриан"}, [8]={hint="Воскресните, найдите могильный камень, о котором говорил Гаэриан."}, [9]={npc="Подозрительное надгробие", npcObj=true}, [10]={npc="Подозрительное надгробие", npcObj=true}, [11]={text="Используйте Механический йети на Поливалка в Прибамбасск (51.06, 26.87), затем идите по южной дороге в Ун'Горо."}, [12]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [13]={hint="Отыщите Восточный хрустальный пилон в Кратере Ун'Горо."}, [14]={hint="С помощью предметов из мешочка Торвы выманите Лар'корви и сразите его. Принесите голову Лар'корви землепроходцу Торве ко входу в Кратер Ун'Горо.", desc="Откройте сумку Торвы. Положите мясо, затем используйте феромоны, чтобы приманить Лар'корви."}, [15]={hint="Принесите 2 шкуры Ун'Горской гориллы, 2 шкуры Ун'Горского топтуна и 2 шкуры Ун'Горского рокотуна землепроходцу Торве к входу в Кратер Ун'Горо.", tag="Цель: Ун'горская горилла / Ун'горская горилла / Ун'Горский топотун / Ун'Горский рокотун"}, [16]={hint="Отыщите Северный хрустальный пилон в Кратере Ун'Горо."}, [17]={hint="Доставьте превосходный меч Линкена Линкену в Кратер Ун'Горо."}, [18]={npc="Линкен", tgt="Линкен"}, [19]={npc="Линкен", tgt="Линкен"}, [20]={hint="Найдите Джей Ди Колли в Укрытии Маршалла."}, [21]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [22]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [23]={npc="Муча Кусора", tgt="Муча Кусора"}, [24]={hint="Возьмите механического йети Уми и напугайте им ее друзей:", desc="Используйте йети на Квикксиль после первых двух целей. Сдайте по адресу Теснина Ледяного Шепота."}, [25]={hint="Отыщите Западный хрустальный пилон."}, [26]={npc="Кракл", tgt="Кракл"}, [27]={hint="Выясните, где находится точка самой высокой температуры на Вулкане Огненного Венца, по просьбе Кракла из Кратера Ун'Горо.", desc="Подождите, пока засчитается реакция. Держитесь подальше от лавы."}, [28]={hint="Найдите Ринго на Вулкане Огненного Венца."}, [29]={npc="Ринго", tgt="Ринго"}, [30]={npc="Ринго", tgt="Ринго", desc="Прежде чем сопровождать, очистите вход в пещеру. Пробуждение Ринго с помощью Фляга Спрэггл."}, [31]={hint="Отведите Ринго к Муче Кусора в Укрытие Маршалла."}, [32]={npc="Муча Кусора", tgt="Муча Кусора"}, [33]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [34]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [35]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [36]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [37]={hint="Поговорите с Джей Ди Колли через пару минут."}, [38]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [39]={npc="Кракл", tgt="Кракл"}, [40]={npc="Кракл", tgt="Кракл"}, [41]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [42]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [43]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [44]={hint="Принесите шкуру Учи землепроходцу Торве ко входу в Кратер Ун'Горо.", desc="Очистите горилл у входа в пещеру. У'ча — обычный моб."}, [45]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [46]={npc="Землепроходец Торва", tgt="Землепроходец Торва", tag="Необязательно", desc="Поверните к Торве через юго-восточный вход. Выберите кожаную броню или посох.", star={"Седая шкура", {"DRUID"}}}, [47]={text="Воспользуйтесь северо-западным съездом Ун'Горо в Силитус. Следуйте по дороге к Крепость Кенария."}}},
    ["05-d31"] = {name="Терраса Создателя", entrance="Кратер Ун'Горо (Во Внутренние земли), 48.10, 6.10. Обозначает структуру Титан. Точные координаты портала неизвестны.", pickup="По пути к Лунная поляна остановитесь у Майена Паломница Земли на северо-западе Мулгор, проезжая через Громовой Утес. Вернувшись в Укрытие Маршалла, поднимитесь по каменной лестнице на север к строению титанов. NPC для двух других квестов не проверены.", pickupS={{"По пути к Лунная поляна остановитесь у Майена Паломница Земли на северо-западе Мулгор, проезжая через Громовой Утес"}, {"Вернувшись в Укрытие Маршалла, поднимитесь по каменной лестнице на север к строению титанов"}, {"NPC для двух других квестов не проверены"}}, tips={{k="動線", text="Вход → соберите четыре цвета кристаллов в руинах титанов → выполните задачи бассейна с помощью Бесцветного кристалла. Полный заказ на титана-дракона Электр, Витрикс и Нанайя остается неподтвержденным."}, {k="取捨", text="Сначала возьмите Crystalline Elements. Если в лагере нет других квестов, входите своей группой."}, {k="說明", text="Новое подземелье для пяти игроков в Forever. Идите в гору к северу от Укрытие Маршалла. Используйте кристаллы силы из Ун'Горо у ворот титанов. Ориентир внешнего входа находится около 48.10, 6.10. Точное место портала не подтверждено.", s={{"Новое подземелье для пяти игроков в Forever"}, {"Идите в гору к северу от Укрытие Маршалла"}, {"Используйте кристаллы силы из Ун'Горо у ворот титанов"}, {"Ориентир внешнего входа находится около 48.10, 6.10"}, {"Точное место портала не подтверждено"}}}, {k="提醒", text="Новое подземелье для пяти игроков в Forever. Идите в гору к северу от Укрытие Маршалла. Используйте кристаллы силы из Ун'Горо у ворот титанов. Ориентир внешнего входа находится около 48.10, 6.10. Точное место портала не подтверждено.", s={{"Новое подземелье для пяти игроков в Forever"}, {"Идите в гору к северу от Укрытие Маршалла"}, {"Используйте кристаллы силы из Ун'Горо у ворот титанов"}, {"Ориентир внешнего входа находится около 48.10, 6.10"}, {"Точное место портала не подтверждено"}}}}, steps={[1]={npc="Майена Паломница Земли", tgt="Майена Паломница Земли", desc="Возьмите на западном утесе в Громовой Утес. NPC взяты из записей игроков."}, [2]={npc="Химик Барабос", tgt="Химик Барабос", tag="Требуется внутриигровая проверка", desc="Пикап NPC и координаты не подтверждены. Проверьте подсказки квеста снаружи."}, [3]={npc="Мастер аптекарь Фаранелл", tgt="Мастер аптекарь Фаранелл", tag="Требуется внутриигровая проверка", desc="Пикап NPC и координаты не подтверждены."}, [4]={text="Вход: Терраса Создателя"}, [5]={hint="Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace.", tag="Требуется внутриигровая проверка", desc="Место: Следуйте к руинам титанов и соберите кристаллы всех четырех цветов у элементалей.", spot="Следуйте к руинам титанов и соберите кристаллы всех четырех цветов у элементалей."}, [6]={hint="Gather 8 Seeping Slime Essence in the Shaper's Terrace.", tag="Требуется внутриигровая проверка", desc="Место: Найдите внутри просачивающуюся слизь. Их точное расположение бассейна не подтверждено.", spot="Найдите внутри просачивающуюся слизь. Их точное расположение бассейна не подтверждено."}, [7]={hint="Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace.", desc="Место: Найдите на земле вокруг Бесцветного кристалла истощенный фрагмент.", spot="Найдите на земле вокруг Бесцветного кристалла истощенный фрагмент."}, [8]={npc="Майена Паломница Земли"}, [9]={npc="Химик Барабос", tgt="Химик Барабос", tag="Требуется внутриигровая проверка"}, [10]={tag="Требуется внутриигровая проверка"}}},
    ["04-56"] = {name="Силитус", tips={{k="交通", text="Открывание Крепость Кенария пункт полёта на шаге 1. На последнем этапе верните дирижабль обратно на Восточные королевства."}, {k="取捨", text="Сохраните Реликварий Чистоты и Умбер, архивариус для сдачи Лунная поляна."}, {k="取捨", text="Пропустите Потерянная сумка Ноггла и РОЗЫСК: Смертехват, гроза пустыни, если вы повышаете уровень. Квест Потерянная сумка Ноггла отправляет вас обратно на далекий юг, а РОЗЫСК: Смертехват, гроза пустыни требует элитного убийства."}, {k="取捨", text="Квест Тенекрыл видео (Проклятый Тенекрыл) находится в Восточные Чумные земли. Также пропустите квесты элитной группы в Силитус."}, {k="提醒", text="Отправляйтесь в Бастион, даже если уровень ниже 59. Чтобы сначала гриндить, убейте обычных скорпидов и пауков к северо-востоку от Крепость Кенария (около 55, 29) или культистов Сумеречный дракон к юго-западу (около 38, 44).", s={{"Отправляйтесь в Бастион, даже если уровень ниже 59"}, {"Чтобы сначала гриндить, убейте обычных скорпидов и пауков к северо-востоку от Крепость Кенария (около 55, 29) или культистов Сумеречный дракон к юго-западу (около 38, 44)"}}}}, danger={[1]="Достижение вершины башни Деревня Южного Ветра вызывает появление рой силитидов. Сначала очистите башню и лестницу, чтобы у вас был выход."}, grind={[1]={mob="Мститель из культа Сумеречного Молота", note="Обычные культисты Сумеречный дракон за пределами лагеря являются хорошими опыт и сбрасывают снаряжение Сумеречный дракон. Сочетайте с культистскими квестами. Убирайтесь с края, если другие занимаются фермерством."}, [2]={mob="Землечерп", note="Обычные мобы на поляне к северо-востоку от Крепость Кенария немного более низкого уровня, но плотные. Ферма на маршруте сбора материалов, если лагерь Сумеречный дракон занят."}}, supply={[1]={npc="Рунк Покоритель Ветров"}, [2]={npc="Каландрата"}, [3]={npc="Варгус"}, [4]={npc="Каландрата"}, [5]={npc="Каландрата"}, [6]={npc="Кхур Острый Рог"}}, steps={[1]={nodeA="{a:3425}", desc="Открывание Орда пункт полёта с Рунк Покоритель Ветров на Крепость Кенария."}, [2]={text="привяжите свой камень возвращения в гостинице (51.89, 39.16), если хотите использовать его после Погост Отважных."}, [3]={hint="Поговорите с призывательницей ветров Гордый Рог в крепости Кенария."}, [4]={npc="Призывательница ветров Гордый Рог", tgt="Призывательница ветров Гордый Рог"}, [5]={npc="Битисса Шаткобрус", tgt="Битисса Шаткобрус"}, [6]={npc="Призывательница ветров Гордый Рог", tgt="Призывательница ветров Гордый Рог"}, [7]={npc="Геолог Ехидная", tgt="Геолог Ехидная"}, [8]={npc="Бор Буйногривый", tgt="Бор Буйногривый"}, [9]={hint="Принесите Битиссе Шаткобрус из крепости Кенария 8 жал камнехвостых скорпидов и 8 жвал песчаных пауков-быстроногов."}, [10]={hint="Убейте 15 землечерпов по поручению призывательницы ветров Гордый Рог."}, [11]={hint="Поговорите с Лайо Зведным Всполохом близ кладбища Покой Доблестных в Силитусе и покажите ему письмо Рабина."}, [12]={npc="Лайо Звездный Всполох", tgt="Лайо Звездный Всполох"}, [13]={npc="Лайо Звездный Всполох", tgt="Лайо Звездный Всполох"}, [14]={hint="Геолог Ехидная из крепости Кенария просит вас собрать 8 фрагментов сумеречной таблички."}, [15]={hint="Принесите 10 зашифрованных Сумрачных текстов Бору Буйногривому в крепость Кенария."}, [16]={npc="Битисса Шаткобрус", tgt="Битисса Шаткобрус"}, [17]={npc="Призывательница ветров Гордый Рог", tgt="Призывательница ветров Гордый Рог"}, [18]={npc="Геолог Ехидная", tgt="Геолог Ехидная"}, [19]={npc="Бор Буйногривый", tgt="Бор Буйногривый"}, [20]={npc="Битисса Шаткобрус", tgt="Битисса Шаткобрус"}, [21]={npc="Призывательница ветров Гордый Рог", tgt="Призывательница ветров Гордый Рог"}, [22]={npc="Геолог Ехидная", tgt="Геолог Ехидная"}, [23]={hint="Убейте 20 земляных сокрушителей по поручению призывательницы ветров Гордый Рог."}, [24]={hint="Принесите Битиссе Шаткобрус из крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов."}, [25]={hint="Отнесите восстановленную табличку отшельнику Ортеллу в Силитус."}, [26]={npc="Отшельник Ортелл", tgt="Отшельник Ортелл"}, [27]={hint="Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне."}, [28]={hint="Освободите в деревне Южного Ветра души 8 истерзанных друидов и 8 истерзанных часовых и вернитесь к Лайо Звездному Всполоху на кладбище Силитуса, Покой Доблестных.", desc="Нежить может вызвать силитида после убийства. Убейте его перед следующим рывком."}, [29]={npc="Лайо Звездный Всполох", tgt="Лайо Звездный Всполох"}, [30]={npc="Лайо Звездный Всполох", tgt="Лайо Звездный Всполох"}, [31]={hint="Осмотрите башню деревни Южного Ветра и отыщите способ разворошить улей. Принесите все необычное, что попадется при выполнении задания Лайо Звездному Всполоху на кладбище Силитуса, Покой Доблестных.", desc="Очистите лестницу башни, прежде чем открывать объект. Следите за своей линией обзора."}, [32]={npc="Лайо Звездный Всполох", tgt="Лайо Звездный Всполох"}, [33]={npc="Лайо Звездный Всполох", tgt="Лайо Звездный Всполох"}, [34]={text="Вернитесь к Крепость Кенария. Очаг, если он привязан сюда."}, [35]={npc="Битисса Шаткобрус", tgt="Битисса Шаткобрус"}, [36]={npc="Призывательница ветров Гордый Рог", tgt="Призывательница ветров Гордый Рог"}, [37]={text="Летите с Крепость Кенария на Оргриммар, затем садитесь на Тирисфальский дирижабль с Дуротар."}}},
    ["04-57"] = {name="Западные Чумные земли", tips={{k="交通", text="Войдите в Оплот на шаге 1. На последнем этапе возьмите дирижабль за пределы Подгород."}, {k="取捨", text="Выполните Поле Джанис и Андорал в одном цикле. На обратном пути сдайте квест с термитами."}, {k="取捨", text="Остальные квесты Хроми отправят вас обратно в Восточные Чумные земли. Сохраните их для обратного пути."}, {k="提醒", text="Ниже 59 уровня? Убейте обычную нежить за пределами восточного Андорала (около 46, 64) или на зараженных фермах, прежде чем отправиться в Оскверненный лес.", s={{"Ниже 59 уровня?"}, {"Убейте обычную нежить за пределами восточного Андорала (около 46, 64) или на зараженных фермах, прежде чем отправиться в Оскверненный лес"}}}}, danger={[1]="Андорал Ратуша находится рядом с Араж Призыватель, элитой 61-го уровня. В поисках Анналы Дарроушира следуйте за внешними стенами."}, grind={[1]={mob="Опаляющий вурдалак", note="Обычная нежить на восточной окраине Андорала. Гринд здесь, прежде чем вернуться на ферму. Избегайте элиты и стаи в зданиях."}, [2]={mob="Призрачное видение", note="Обычные призраки более высокого уровня в Пустошь Гаррона. Используйте это место, если вы все еще на востоке. Закруглите край, чтобы избежать соединения мобов в помещении."}}, supply={[1]={npc="Интендант Хасна из ордена Серебряного Рассвета"}, [2]={npc="Майкл Гарретт"}, [3]={npc="Хозяин таверны Норман"}, [4]={npc="Хозяин таверны Норман"}, [5]={npc="Элинор Руск"}, [6]={npc="Томас Морден"}, [7]={npc="Иезекииль Могиллан"}}, steps={[1]={text="Идите от башни дирижабля Тирисфаля к Оплоту, затем через Поле Джанис, Андорал и Лесопилка Северного Кряжа."}, [2]={hint="Отнесите полную бутылку с пустоши Гаррона жрице Тьмы Вандис в Бастион в Западных Чумных землях."}, [3]={npc="Жрица Тьмы Вандис", tgt="Жрица Тьмы Вандис"}, [4]={npc="Микки Левин", tgt="Микки Левин"}, [5]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон", star={"Доблестный короткий меч", {"PALADIN", "MAGE", "WARLOCK"}}}, [6]={hint="Выполните задачи задания."}, [7]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон", star={"Доблестный короткий меч", {"PALADIN", "MAGE", "WARLOCK"}}}, [8]={npc="Микки Левин", tgt="Микки Левин"}, [9]={hint="Отнесите половинку талисмана Джанис Фелстоун в Западные Чумные земли."}, [10]={npc="Джанис Фелстоун", tgt="Джанис Фелстоун"}, [11]={npc="Джанис Фелстоун", tgt="Джанис Фелстоун"}, [12]={hint="Отыщите вторую половину оберега Удачи на ферме Фелстоун в Западных Чумных землях и соберите его.", desc="Гуль патрулирует ферму. Сначала проверьте южную сторону."}, [13]={npc="Джанис Фелстоун", tgt="Джанис Фелстоун"}, [14]={hint="Поговорите с Марлен в южной части руин Андорала."}, [15]={npc="Марлен Редпат", tgt="Марлен Редпат"}, [16]={npc="Марлен Редпат", tgt="Марлен Редпат"}, [17]={hint="Принесите Хроми обручальное кольцо Джозефа.", desc="Элитный лич находится в центре Андорала. Оставайтесь на окраине по пути в гостиницу."}, [18]={npc="Хроми", tgt="Хроми"}, [19]={npc="Хроми", tgt="Хроми"}, [20]={npc="Хроми", tgt="Хроми"}, [21]={hint="Принесите Анналы Дарроушира Хроми в Андорал.", desc="Проверьте крышку. Поддельные книги могут порождать врагов. Избегайте элит в центре."}, [22]={hint="Воспользуйтесь временным переместителем рядом с одним из амбаров Андорала и найдите временных паразитов."}, [23]={npc="Хроми", tgt="Хроми"}, [24]={npc="Хроми", tgt="Хроми"}, [25]={npc="Хроми", tgt="Хроми"}, [26]={hint="Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях."}, [27]={npc="Хроми", tgt="Хроми"}, [28]={hint="Найдите подходящее место на лесопилке Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов из Чумных земель."}, [29]={npc="Термитная бочка", npcObj=true}, [30]={npc="Термитная бочка", npcObj=true}, [31]={hint="Выпустите термитов с Проклятых земель на лесопилке Северного Кряжа и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.", desc="Открытие бочки привлекает врагов. Сразу отойди, как откроешь её."}, [32]={npc="Микки Левин", tgt="Микки Левин"}, [33]={npc="Скорбящий рыцарь", tag="Необязательно, Требуется внутриигровая проверка", desc="См. Скорбящий рыцарь на юго-западе Тирисфаля. Меч траура — выбор награды.", star={"Sword of Mourning", {"PALADIN"}}}, [34]={text="Вернитесь к башне дирижабля Подгород. Возьмите дирижабль Оргриммар и продолжайте движение к Оскверненный лес."}}},
    ["05-d32"] = {name="Некроситет", entrance="Западные Чумные земли (Угроза с моря), о 68.90, 72.80. Вход в подвал по адресу Каэр Дарроу.", pickup="У Оплота возьмите Сокровище Баровых у Алекси и запустите брелок. Заберите Зачумленные детеныши дракона по адресу Часовня Последней Надежды. Следуйте по южной дороге от Оплота до Каэр Дарроу и прежде чем войти, увидите Еву. Чтобы сделать свой собственный ключ, сдайте Фрагменты скелетов в Оплоте, возьмите квест на изготовление формы, затем посетите Прибамбасск и Вулкан Огненного Венца, прежде чем вернуться в Оплот.", pickupS={{"У Оплота возьмите Сокровище Баровых у Алекси и запустите брелок"}, {"Заберите Зачумленные детеныши дракона по адресу Часовня Последней Надежды"}, {"Следуйте по южной дороге от Оплота до Каэр Дарроу и прежде чем войти, увидите Еву"}, {"Чтобы сделать свой собственный ключ, сдайте Фрагменты скелетов в Оплоте, возьмите квест на изготовление формы, затем посетите Прибамбасск и Вулкан Огненного Венца, прежде чем вернуться в Оплот"}}, tips={{k="動線", text="Входной мост → документ в первом зале → еще один за комнатой призыва → склеп для Громоклин и детенышей → документ в комнате Рас Снегошепот → последний документ и Крастинов внизу → Темный магистр Гандлинг."}, {k="取捨", text="Совершите четыре дела, детенышей чумы и профессора за один заход. Если кто-то может открыть дверь, все остальные могут пропустить цепочку с ключами."}, {k="說明", text="Подземелье для пяти игроков. Пусть ключница откроет внешнюю дверь. Квесты после профессора Мешок ужасов Крастинова и Киртонос Глашатай требуют повторного прохождения. Сохраните их для группы, которая сможет снова бежать.", s={{"Подземелье для пяти игроков"}, {"Пусть ключница откроет внешнюю дверь"}, {"Квесты после профессора Мешок ужасов Крастинова и Киртонос Глашатай требуют повторного прохождения"}, {"Сохраните их для группы, которая сможет снова бежать"}}}, {k="提醒", text="Подземелье для пяти игроков. Пусть ключница откроет внешнюю дверь. Квесты после профессора Мешок ужасов Крастинова и Киртонос Глашатай требуют повторного прохождения. Сохраните их для группы, которая сможет снова бежать.", s={{"Подземелье для пяти игроков"}, {"Пусть ключница откроет внешнюю дверь"}, {"Квесты после профессора Мешок ужасов Крастинова и Киртонос Глашатай требуют повторного прохождения"}, {"Сохраните их для группы, которая сможет снова бежать"}}}}, steps={[1]={npc="Алекcий Баров", tgt="Алекcий Баров", desc="Возьмите рано в Оплоте, как только достигнете уровня 52."}, [2]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", desc="Найдите Беттину по адресу Часовня Последней Надежды."}, [3]={npc="Ева Саркофф", tgt="Ева Саркофф", desc="Найдите Еву за дверью в Каэр Дарроу."}, [4]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон", desc="Делайте это только в том случае, если вам нужен собственный ключ Некроситет. Пропустите, если делаете это в Оплоте."}, [5]={hint="Отправляйтесь в лагерь Алого ордена между полем Джанис и Слезами Далсона и уничтожьте командный шатер."}, [6]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон"}, [7]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон", desc="Уже на главном маршруте у Бастиона в Западные Чумные земли.", preText="Вылазка в стан Алого Марша"}, [8]={hint="Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен."}, [9]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон"}, [10]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон", desc="Вы можете сдать это заранее в Оплоте.", preText="Сторожевые башни"}, [11]={hint="Поговорите с аптекарем Дитерсом из Бастиона, что в Западных Чумных землях."}, [12]={npc="Аптекарь Дитерс", tgt="Аптекарь Дитерс"}, [13]={npc="Аптекарь Дитерс", tgt="Аптекарь Дитерс", desc="Пропустите эти три, если делаете это в Оплоте. Если вы делаете ключ самостоятельно, возьмите форму.", preText="Некроситет"}, [14]={hint="Принесите 15 фрагментов скелетов аптекарю Дитерсу в Бастион в Западных Чумных землях."}, [15]={npc="Аптекарь Дитерс", tgt="Аптекарь Дитерс"}, [16]={npc="Аптекарь Дитерс", tgt="Аптекарь Дитерс", desc="Прежде чем отправиться с Прибамбасск в Укрытие Маршалла, принесите два ториевых слитка.", preText="Фрагменты скелетов"}, [17]={hint="Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет."}, [18]={npc="Кринкель Сталлер", tgt="Кринкель Сталлер"}, [19]={npc="Кринкель Сталлер", tgt="Кринкель Сталлер", desc="Сделайте это с помощью квестов Вулкан Огненного Венца на ветке Укрытие Маршалла.", preText="Форма денег стоит"}, [20]={hint="Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка."}, [21]={npc="Аптекарь Дитерс", tgt="Аптекарь Дитерс"}, [22]={npc="Аптекарь Дитерс", tgt="Аптекарь Дитерс", desc="Сделайте это во время этапа Андорала от Оплота, если у вас есть группа.", preText="Кузня Пламенного хребта"}, [23]={hint="Убейте Аража Призывателя и отнесите его скарабея аптекарю Дитерсу в Бастион, что в Западных Чумных землях."}, [24]={npc="Аптекарь Дитерс", tgt="Аптекарь Дитерс"}, [25]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон", preText="Скарабей Араджи"}, [26]={hint="Выполните задачи задания."}, [27]={npc="Верховный палач Деррингтон", tgt="Верховный палач Деррингтон"}, [28]={text="Вход: Некроситет"}, [29]={hint="Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.", desc="Место: Обыщите первый зал, мимо комнаты призыва, затем комнаты Раса и Барова. Порядок: Южнобережье → Мельница Таррен → Брилл → Каэр Дарроу.", spot="Обыщите первый зал, мимо комнаты призыва, затем комнаты Раса и Барова."}, [30]={hint="Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.", desc="Место: Пройдите комнату призыва и убейте детенышей в костнице Громоклин.", spot="Пройдите комнату призыва и убейте детенышей в костнице Громоклин."}, [31]={hint="Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.", desc="Карта: Крастинов (88.80, 45.50). Останки Евы и Люсьена находятся в комнате. Место: Найдите Крастинова в последних шести комнатах. Горение оба комплекта остаются в его комнате. Порядок: Останки находятся в той же комнате.", spot="Найдите Крастинова в последних шести комнатах. Горение оба комплекта остаются в его комнате."}, [32]={npc="Ева Саркофф", tgt="Ева Саркофф", desc="Возьмите «Мешок ужасов» у Евы в следующий раз. При первом заходе просто сдайтесь."}, [33]={npc="Алекcий Баров", tgt="Алекcий Баров"}, [34]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк"}}},
    ["04-58"] = {name="Оскверненный лес", tips={{k="交通", text="На шаге 1 идите на север от Ясеневый лес. На последнем шаге пройдите от Крепость Древобрюхов до Лунная поляна."}, {k="取捨", text="Квест Окончательный удар требует еще одного путешествия вглубь Оплот Теней для достижения трех целей. Пропустите его, если одиночный забег не стоит потраченного времени."}, {k="取捨", text="Принесите Ядовитый Ужас Источники Ледяного Пламени в Зимние Ключи, чтобы сдать его."}, {k="提醒", text="Ниже 60 уровня? Убейте энтов Ядовитый Ужас и Irontree в Железнолесье (около 49, 25) или догоните их в Зимние Ключи.", s={{"Ниже 60 уровня?"}, {"Убейте энтов Ядовитый Ужас и Irontree в Железнолесье (около 49, 25) или догоните их в Зимние Ключи"}}}}, danger={[1]="Жаровни в Оплот Теней разбросаны по узким туннелям. Очистите каждую секцию, прежде чем заливать жаровню. Повторите свои шаги, чтобы выбраться."}, grind={[1]={mob="Ядовитый ужас", note="Обычные элементали из пула Железнолесье. Собирайте капли Ядовитый ужас на ходу. Они хороши для небольшого зазора опыт. Перейдите к Зимние Ключи, если пул занят."}, [2]={mob="Криводрев-живорез", note="Обычные энты у северной дороги. Переключитесь сюда, если бассейн занят, и продолжайте движение по дороге к Крепость Древобрюхов. Следите за кастингистами внутри лагеря."}}, supply={[1]={npc="Хозяйка таверны Кайлиска"}, [2]={npc="Хозяйка таверны Кайлиска"}, [3]={npc="Браккар"}, [4]={npc="Альтсоба Тотем Гнева"}, [5]={npc="Тюкн"}, [6]={npc="Тюкн"}}, steps={[1]={text="Перелет из Оргриммар в Застава Расщепленного Дерева. Следуйте по главной дороге на север до Оскверненный лес и остановитесь на Изумрудное святилище и идите вдоль близлежащей дороги."}, [2]={npc="Майбесса Речной Ветер", tgt="Майбесса Речной Ветер"}, [3]={hint="Отнесите очищенную воду из лунного колодца Грете Замшелому Копыту в Оскверненный лес."}, [4]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [5]={hint="Найдите Эридану Грусть Ветра на юге Оскверненного леса."}, [6]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [7]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [8]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [9]={hint="При помощи очищенной воды из лунного колодца загасите пламя в четырех жаровнях защиты внутри Оплота Теней в Оскверненном лесу. Затем возвращайтесь к Грете Замшелому Копыту в Изумрудное святилище.", desc="Сначала очистите проход. Отметки на карте могут перекрываться внутри пещеры."}, [10]={hint="Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра.", desc="Добывайте серебряные когти у волков и медведей. Убейте энтов Железного Дерева ради сердца."}, [11]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [12]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [13]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто", tag="Необязательно", desc="Вернитесь вглубь Оплот Теней с напарником или, если можете, вытаскивайте мобов по одному."}, [14]={hint="Убейте Моору и Салию и принесите голову владыки теней Скверн'дана Грете Замшелому Копыту в Оскверненный лес.", tag="Необязательно", desc="Охранники близки к лорду. Сначала очистите ближайший патруль."}, [15]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто", tag="Необязательно"}, [16]={npc="Трулл Баловень Судьбы", tgt="Трулл Баловень Судьбы"}, [17]={hint="Соберите 3 капли ядовитого ужаса и принесите их Донове Снегоноре в Зимние Ключи."}, [18]={npc="Бесенок", tgt="Бесенок", tag="Необязательно", desc="Жнец душ — один из вариантов вознаграждения.", star={"Жнец душ", {"WARLOCK"}}}, [19]={hint="Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест.", tag="Необязательно", desc="Вернитесь к Бесенок, если собрали все по ногам на остановках 45, 52 и 57."}, [20]={npc="Бесенок", tgt="Бесенок", tag="Необязательно"}, [21]={npc="Бесенок", tgt="Бесенок", tag="Необязательно", desc="Собирайтесь в элиту. Сдайтесь Ниби, чтобы разблокировать Инфернал."}, [22]={hint="Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождать, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.", tag="Необязательно", desc="Собирайтесь в элиту. Сдайтесь Ниби, чтобы разблокировать Инфернал."}, [23]={npc="Ниби Всемогущий", tgt="Ниби Всемогущий", tag="Необязательно", desc="Собирайтесь в элиту. Сдайтесь Ниби, чтобы разблокировать Инфернал."}, [24]={text="Идите на север в Крепость Древобрюхов и сверните на съезд Лунная поляна."}}},
    ["04-59"] = {name="Лунная поляна", tips={{k="交通", text="Идите к Ночная Гавань на шаге 1. На последнем этапе отправляйтесь к Источники Ледяного Пламени или Круговзор, в зависимости от ваших квестов."}, {k="取捨", text="Выполните передачу обоих NPC Ночная Гавань за одно посещение деревни."}, {k="取捨", text="Сохраните Осколки сквернита для пробега Забытый Город на восток."}, {k="提醒", text="Эта нога по-прежнему предназначена для уровней 59-60. Когда закончите, перейдите прямо к Теснина Ледяного Шепота.", s={{"Эта нога по-прежнему предназначена для уровней 59-60"}, {"Когда закончите, перейдите прямо к Теснина Ледяного Шепота"}}}}, danger={[1]="Проверьте репутацию Timbermaw, прежде чем переходить с Лунная поляна на Зимние Ключи. Если вы по-прежнему враждебны, поднимите свою репутацию на стороне Оскверненный лес, прежде чем войти в туннель."}, grind={[1]={mob="Бешеный щербозуб", note="После выполнения квеста Лунная поляна пройдите через трюм и убейте обычных медведей возле северного устья Теснина Ледяного Шепота. Их около 60. Избегайте представителей элиты ниже."}}, supply={[1]={npc="Мелири"}, [2]={npc="Даргон"}, [3]={npc="Даолин Летний Лист"}, [4]={npc="Фаустрон"}}, steps={[1]={text="Покиньте Крепость Древобрюхов и следуйте по главной дороге до Ночная Гавань. Сдайте оба предмета из Силитус."}, [2]={npc="Рабин Сатурна", tgt="Рабин Сатурна"}, [3]={hint="Отнесите покрытый коркой предмет Умберу - архивариусу Круга Кенария - в деревню Ночная Гавань, что в Лунной поляне."}, [4]={npc="Умбер", tgt="Умбер"}, [5]={npc="Умбер", tgt="Умбер"}, [6]={hint="Поговорите с Рабином Сатурной в деревне Ночная Гавань в Лунной поляне."}, [7]={npc="Рабин Сатурна", tgt="Рабин Сатурна"}, [8]={npc="Умбер", tgt="Умбер"}, [9]={hint="Выполните задачи задания."}, [10]={npc="Умбер", tgt="Умбер"}, [11]={text="С помощью Новые источники или Ядовитый Ужас вернитесь через Крепость Древобрюхов к горячим источникам Зимние Ключи. Если у вас нет ни того, ни другого и вы пропускаете Донову, летите в Круговзор из Фаустрон (32.09, 66.61)."}}},
    ["04-60"] = {name="Зимние Ключи", tips={{k="交通", text="Сначала остановитесь на Источники Ледяного Пламени. После сдачи квестов йети Круговзор идите на юг и пройдите мимо северного входа в ущелье."}, {k="取捨", text="Ищите одиноких курьеров для Гонцы Зимней Спячки. Исследовательский квест Выяснение причин находится на пути к месту шлифования видео."}, {k="取捨", text="Квест Верховный вождь племени Зимней Спячки имеет элитную цель. Вместо этого убивайте обычных медведей, если будете в одиночку."}, {k="提醒", text="Ниже 60 уровня? Следуйте видео и измельчите медведей к северу от Теснина Ледяного Шепота. QuestieDB перечисляет обычные Обезумевший Shardtooth, которые появляются вокруг 57.63, 70.83 и 66.68, 70.57. Избегайте элит внизу.", s={{"Ниже 60 уровня?"}, {"Следуйте видео и измельчите медведей к северу от Теснина Ледяного Шепота"}, {"QuestieDB перечисляет обычные Обезумевший Shardtooth, которые появляются вокруг 57.63, 70.83 и 66.68, 70.57"}, {"Избегайте элит внизу"}}}}, danger={[1]="Элитные гиганты Ледяного Молота 59-60 уровней бродят по Теснина Ледяного Шепота. Тяните медведей по одному вдоль склона у северного входа и не тащите их в ущелье.", [2]="Элитные Убийцы Хедерин 57-60 уровней бродят по Теснина Зловещего Шепота. Детонатор Выяснение причин у северного входа, затем вернитесь на дорогу."}, grind={[1]={mob="Бешеный щербозуб", note="Обычная атака ближнего боя к западу от северного устья Теснина Ледяного Шепота. Вытаскивайте по одному врагу и снимайте с него шкуру. После зачистки поверните на восток. Избегайте элиты ниже."}, [2]={mob="Бешеный щербозуб", note="Обычные медведи к востоку от северного устья ущелья. Переключитесь сюда, если западная сторона занята или не возродилась. Тяните в гору к дороге подальше от элиты."}}, supply={[1]={npc="Югрек"}, [2]={npc="Хозяйка таверны Виззи"}, [3]={npc="Низзрак"}, [4]={npc="Хозяйка таверны Виззи"}, [5]={npc="Виззрак"}}, steps={[1]={text="Из Крепость Древобрюхов см. Донову у горячих источников. Сдайте квесты Укрытие Маршалла и Железнолесье, затем отправляйтесь в Круговзор и южную долину. Если вы прилетели прямо в Круговзор и пропускаете квесты на горячие источники, начните с Уми."}, [2]={hint="Отправьтесь в Зимние Ключи и побеседуйте с Доновой Снегонорой."}, [3]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [4]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [5]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [6]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [7]={hint="Найдите гонцов из племени Зимней Спячки и не позвольте им донести их груз до их деревни.", desc="Найдите одинокого курьера возле входа в Древобрюх или котел Мертвого леса."}, [8]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [9]={npc="Донова Снегонора", tgt="Донова Снегонора", tag="Необязательно", desc="Соберитесь с элитой 59-го уровня и ближайшими фурболгами."}, [10]={hint="По просьбе Доновы Снегоноры из Зимних Ключей убейте верховного вождя племени Зимней Спячки.", tag="Необязательно", desc="Сначала очистите внешних мобов. Следуйте инструкциям, если письмо упадет и вам понадобится цепочка."}, [11]={npc="Неразборчиво исписанный журнал", npcObj=true, tag="Необязательно", desc="Щелкните журнал правой кнопкой мыши, если Верховный вождь племени Зимней Спячки удаляет его."}, [12]={hint="Отнесите неразборчиво исписанный журнал Донове Снегоноре в Зимние Ключи.", tag="Необязательно"}, [13]={npc="Донова Снегонора", tgt="Донова Снегонора", tag="Необязательно"}, [14]={npc="Донова Снегонора", tgt="Донова Снегонора", tag="Необязательно"}, [15]={npc="Юми Румпельшникер", tgt="Юми Румпельшникер"}, [16]={hint="Последуйте указаниям Доновы Снегоноры, а затем вернитесь к ней.", desc="Остановитесь у входа в ущелье. Избегайте элит внутри себя."}, [17]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [18]={text="Ниже 60 уровня? Убейте обычных Обезумевший Осколочнозубых медведей возле северного входа в ущелье."}}},
    ["05-d34"] = {name="Верхняя часть пика Черной горы", entrance="Тлеющее ущелье (1427), 34.80, 85.30. Отмечает приближение к Черная гора.", pickup="На 55 уровне летите с Круговзор на Оргриммар и на дирижабле добирайтесь до Восточные королевства. Выполните квест Приказ полководца Lower Вершина Черной горы, затем возьмите Мудрость Эйтригга у Полководец Клинозуб в Каргат. После Кабестан см. Эйтригг и Тралл в Аллея Мудрости и сохраните За Орду!. На уровне 57 возьмите Вивиан Лягроб и табличка Темнокамня в апотекарии Подгород, затем летите к Каргат, чтобы сдаться Вивиан и взять Табличка Темнокамня. Имейте хотя бы одного члена группы. закончить Печать Вознесения → Печать Вознесения и принести печать. Если у кого-то он уже есть, переходите сразу в Upper Вершина Черной горы.", pickupS={{"На 55 уровне летите с Круговзор на Оргриммар и на дирижабле добирайтесь до Восточные королевства"}, {"Выполните квест Приказ полководца Lower Вершина Черной горы, затем возьмите Мудрость Эйтригга у Полководец Клинозуб в Каргат"}, {"После Кабестан см"}, {"Эйтригг и Тралл в Аллея Мудрости и сохраните За Орду!"}, {"На уровне 57 возьмите Вивиан Лягроб и табличка Темнокамня в апотекарии Подгород, затем летите к Каргат, чтобы сдаться Вивиан и взять Табличка Темнокамня"}, {"Имейте хотя бы одного члена группы. закончить Печать Вознесения → Печать Вознесения и принести печать"}, {"Если у кого-то он уже есть, переходите сразу в Upper Вершина Черной горы"}}, tips={{k="動線", text="Очистите семь рун → Пиростраж Созерцатель Углей → табличка в лежбище → Зал Чернорука → Кровопускание и Гит на арене → кузница, с дополнительным Зверь → Генерал Драккисат на троне и его клеймо позади него."}, {k="取捨", text="Сначала возьмите квесты Каргат и Оргриммар. Выполняйте Приказ Чернорука только в том случае, если вам нужна настройка рейда."}, {k="說明", text="Используйте общий вход с Lower Вершина Черной горы. Поднимитесь налево, чтобы найти запертую верхнюю дверь. Приведите кого-нибудь с Печать Вознесения. Направляющие Запуск показывают порядок ворот. Если трамплины преграждают вам путь, воспользуйтесь внешним верхним проходом.", s={{"Используйте общий вход с Lower Вершина Черной горы"}, {"Поднимитесь налево, чтобы найти запертую верхнюю дверь"}, {"Приведите кого-нибудь с Печать Вознесения"}, {"Направляющие Запуск показывают порядок ворот"}, {"Если трамплины преграждают вам путь, воспользуйтесь внешним верхним проходом"}}}}, steps={[1]={npc="Полководец Клинозуб", tgt="Полководец Клинозуб", desc="Если окно квеста не открывается, поговорите с NPC и используйте заказы из сумок."}, [2]={hint="Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат.", desc="Документ может перемещаться. Проверьте каждую из первых трех комнат, когда доберетесь до нее. Карта: Омокк 35.10,55.30; Вооне 52.50,54.90; Вирмталак 57.80,60.50. Проверьте каждую комнату."}, [3]={npc="Полководец Клинозуб", tgt="Полководец Клинозуб"}, [4]={npc="Полководец Клинозуб", tgt="Полководец Клинозуб", preText="Приказ полководца"}, [5]={hint="Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу."}, [6]={npc="Тралл", tgt="Тралл"}, [7]={npc="Тралл", tgt="Тралл", preText="Мудрость Эйтригга"}, [8]={npc="Аптекарь Зинг", tgt="Аптекарь Зинг", tag="Необязательно", desc="Возьмите номер 57 в аптеке Подгород. Пропустите этот вариант, если у вас Табличка Темнокамня."}, [9]={hint="Переговорите с темным магом Вивианой Лягроб.", tag="Необязательно"}, [10]={npc="Темный маг Вивиана Лягроб", tgt="Темный маг Вивиана Лягроб", tag="Необязательно"}, [11]={npc="Темный маг Вивиана Лягроб", tgt="Темный маг Вивиана Лягроб", desc="Заберите у Вивиан, если предложите. В противном случае начните с Вивиан Лягроб и табличка Темнокамня в Подгород."}, [12]={npc="Распоряжения Ренда Чернорука", npcObj=true, tag="Необязательно", desc="Найдите и используйте письмо интенданта возле Вершина Черной горы, чтобы получить доступ к BWL."}, [13]={text="Вход: Верхняя часть пика Черной горы"}, [14]={hint="Пойдите в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар.", desc="Верхняя карта Вершина Черной горы 3: Вождь Ренд Чернорук (48.60, 25.60). Место: Передайте лежбище в Зал Чернорука. Войдите в северные ворота арены, чтобы активировать Кровопускание. Порядок: Возьмите планшет из инкубатория перед ареной.", spot="Передайте лежбище в Зал Чернорука. Войдите в северные ворота арены, чтобы активировать Кровопускание."}, [15]={hint="Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат.", desc="Оставайтесь на пути и избегайте яиц. Яйца Сломленный порождают детенышей. Место: После Пиростраж Созерцатель Углей войдите в лежбище. Проверьте пол у стены. Порядок: Сделайте это перед ареной в шаге 13.", spot="После Пиростраж Созерцатель Углей войдите в лежбище. Проверьте пол у стены."}, [16]={hint="Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.", tag="Необязательно", desc="Карта УБРС 3: Генерал Драккисат (34.80, 50.10). Бренд стоит за ним. Место: Выйдите из южных ворот арены и пройдите через кузницу. Бренд стоит за боссом. Порядок: Убейте Драккисата, затем щелкните Клеймо позади него.", spot="Выйдите из южных ворот арены и пройдите через кузницу. Бренд стоит за боссом."}, [17]={npc="Клеймо Драккисата", npcObj=true, tag="Необязательно, Требуется внутриигровая проверка", spot="Клеймо Дракисата за его троном"}, [18]={npc="Тралл", tgt="Тралл"}, [19]={npc="Темный маг Вивиана Лягроб", tgt="Темный маг Вивиана Лягроб"}}},
    ["05-d33"] = {name="Blackmaw Hold", entrance="Зимние Ключи 66.60, 84.40", pickup="Возьмите Средь корней Нордрассила у Джедиги в Валормоке и Когти и бивни у Огтинка. Вернитесь в Азшару за Эккалом на уровне 55. Когда вы вернетесь в Калимдор через Рэтчета, летите к Elder Rise в Громовом Утесе, сдайте письмо Джедиги и возьмите Докопаться до корней. Посетите Мулна Ярость Земли в Мулгоре. Летите в Валормок и войдите через туннель Азшары. Сохраните Докопаться до корней и Магия Черночревов для следующего визита в Громовой Утес и Мулгор.", pickupS={{"Возьмите Средь корней Нордрассила у Джедиги в Валормоке и Когти и бивни у Огтинка"}, {"Вернитесь в Азшару за Эккалом на уровне 55"}, {"Когда вы вернетесь в Калимдор через Рэтчета, летите к Elder Rise в Громовом Утесе, сдайте письмо Джедиги и возьмите Докопаться до корней"}, {"Посетите Мулна Ярость Земли в Мулгоре"}, {"Летите в Валормок и войдите через туннель Азшары"}, {"Сохраните Докопаться до корней и Магия Черночревов для следующего визита в Громовой Утес и Мулгор"}}, tips={{k="動線", text="Найдите мешочки Черной Пасти во входных туннелях → соберите подземные шляпки Нордрассила → ветки для Сухозев и Костерыл Несломленный → Старейшина-шаман Кровогрив для ритуального тотема. Точные вилки и порядок босса не подтверждены."}, {k="取捨", text="Выполняйте приготовления Огтинк и Руины Эльдарата по ходу прохождения. Завершите цепочку rootcap Орда за одно посещение Громовой Утес."}, {k="說明", text="Значок портала появится на карте Зимние Ключи. Войдите в туннель фурболгов в Азшара (38.70, 33.40) и следуйте по нему к порталу. Не ищите его на поверхности Зимние Ключи.", s={{"Значок портала появится на карте Зимние Ключи"}, {"Войдите в туннель фурболгов в Азшара (38.70, 33.40) и следуйте по нему к порталу"}, {"Не ищите его на поверхности Зимние Ключи"}}}}, steps={[1]={npc="Джедига", tgt="Джедига", tag="Требуется внутриигровая проверка"}, [2]={hint="Поговорите с Нарой Буйной Гривой на Вершине Старейшин Громового Утеса.", tag="Требуется внутриигровая проверка"}, [3]={npc="Нара Буйногривая", tgt="Нара Буйногривая", tag="Требуется внутриигровая проверка"}, [4]={npc="Нара Буйногривая", tgt="Нара Буйногривая", tag="Требуется внутриигровая проверка", preText="Средь корней Нордрассила"}, [5]={npc="Огтинк", tgt="Огтинк"}, [6]={npc="Алаана Штормовой Полет", tgt="Muln Earthfury", desc="Используйте метку Мулгор на пути к Громовой Утес."}, [7]={npc="Эккаль", tgt="Эккаль", desc="Руины Эльдарата, Азшара. Минимальный уровень получения — от DungeonsForever."}, [8]={text="Вход: Blackmaw Hold"}, [9]={hint="Добудьте 10 апексов корней Нордрассила в логове Черночревов для Нары Буйной Гривы из Громового Утеса.", tag="Требуется внутриигровая проверка", desc="Место: Следуйте по проходам к подземным корням и соберите там корневища.", spot="Следуйте по проходам к подземным корням и соберите там корневища."}, [10]={hint="Принесите когти Великого Медведя и бивни Несломленного Огтинку в Азшару.", tag="Цель: Великан Медведь Сухозев / Костерыл Несломленный, Требуется внутриигровая проверка", desc="Место: Найдите Сухозев и Костерыл Несломленный в туннелях. Форк не подтвержден.", spot="Найдите Сухозев и Костерыл Несломленный в туннелях. Форк не подтвержден."}, [11]={hint="Раздобудьте в логове Черночревов ритуальный тотем Черночревов.", tag="Требуется внутриигровая проверка", desc="Место: Следуйте по маршруту босса к Старейшина-шаман Кровогрив и заберите его ритуальный тотем.", spot="Следуйте по маршруту босса к Старейшина-шаман Кровогрив и заберите его ритуальный тотем."}, [12]={hint="Проникните в логово Черночревов, соберите 5 |4кошель:кошеля:кошелей; Черночревов и принесите Эккалю в руины Эльдарата, что в Азшаре.", desc="Место: Очистите оскверненных фурболгов Черной Пасти в жилых помещениях и мешочках с добычей.", spot="Очистите оскверненных фурболгов Черной Пасти в жилых помещениях и мешочках с добычей."}, [13]={npc="Огтинк", tgt="Огтинк"}, [14]={npc="Эккаль", tgt="Эккаль"}, [15]={npc="Нара Буйногривая"}, [16]={npc="Алаана Штормовой Полет", tgt="Muln Earthfury", desc="QuestieDB перечисляет Мулн Гнев Земли в Мулгор. Сдавшийся NPC и координаты не подтверждены."}}},
  },
  quests = {
    [2] = {n="Коготь гиппогрифа Острокогтя", d="Принесите коготь гиппогрифа Острокогтя Сенани Громосерд на заставу Расщепленного Древа в Ясеневом лесу."},
    [10] = {n="Спасение Холстомера", d="Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск.", objs={"Обозревательное устройство Холстомера"}},
    [23] = {n="Лапа Топтыжня", d="Принесите лапу Топтыжня Сенани Громовое Сердце на заставу Расщепленного Древа в Ясеневом лесу."},
    [24] = {n="Голова Тенумбры", d="Принесите голову Тенумбры Сенани Громовое Сердце на заставу Расщепленного Древа в Ясеневом лесу."},
    [25] = {n="Остановка у Каменного Когтя", d="Истребите 12 злобных элементалей воды на озере Мистраль, что к востоку от Туннеля Когтя и к юго-западу от заставы Расщепленного Древа.\nИсследуйте беседку на озере Мистраль, из которой открывается вид на соседний форт Альянса.\nВернитесь к Мастоку Райльшипу на заставу Расщепленного Древа в Ясеневом лесу.", tgo={{"Злобный элементаль воды"}}},
