    [2284] = {n="Пропавшее ожерелье, этап 2", d="Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана."},
    [2318] = {n="Трудности перевода", d="Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях."},
    [2338] = {n="Трудности перевода", d="Одолжите ожерелье Джаркалу. Взамен он переведет дневник."},
    [2339] = {n="Найти самоцветы и источник энергии", d="Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане.\nИз дневника следует...\n* Рубин спрятан на огражденной завалами территории Кузни Теней.\n*Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.\n*Сапфир забрал Гримлок, старейшина троггов.", tgo={{}, {"Гримлок"}, {}, {"Аркедас"}}, objs={"Тайник Кузни Теней", "Подозрительная урна"}},
    [2340] = {n="Принести самоцветы", d="Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар."},
