    [2381] = {n="Грабь награбленное", d="Принесите Рениксу Презренному из Кабестана сокровище Южного моря. Не забудьте взять из гизмотронного аппарата Реникса ХОЧУ и отмычки. Они понадобятся для выполнения задания.\nЕсли на вас нападут необычайно враждебные попугаи, воспользуйтесь ХОЧУ!", tgo={{"Полли"}}},
    [2382] = {n="Реникс из Кабестана", d="Поговорите с Рениксом Презренным в Кабестане."},
