    [2458] = {n="Надежное прикрытие", d="Отыщите башню Торговой компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.\nВозле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и продемонстрируйте приветствие Изувеченной Длани (команда /честь).\nВсе нужно делать строго по порядку - Физзул убивает всех, кто кажется ему подозрительным."},
    [2460] = {n="Приветствие Изувеченной Длани", d="Повторите приветствие Раздробленной Руки вслед за Шентулом.", tgo={{"Шентул"}}},
    [2478] = {n="Миссия: выполнима, но с трудом", d="Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой компании, двух патрульных Торговой компании и двух смотрителей Торговой компании.\nЛиквидируйте старшего мастера Галливикса, взломайте замок на его ящике и украдите запас измененной смеси Занзила. Отнесите запас смеси и голову Галливикса Шентулу в Оргриммар и получите следующие указания.", tgo={{"Мутировавший мертвяк Торговой компании"}, {"Наблюдатель Торговой компании"}, {"Патрульный Торговой компании"}, {"Старший штейгер Пузик Нервотреп"}, {"Штейгер Силиксиз"}, {}}, objs={"Денежный ящик Галливикса"}},
    [2479] = {n="Помощь Хинотта", d="Пойдите на Мельницу Таррен в предгорьях Хилсбрада и доставьте образчик смеси Занзила Сержу Хинотту.\nСядьте на дирижабль, идущий до Подгорода, и летите вдоль дороги на юг, через Серебряный бор в сторону Хилсбрада. Следите за знаками."},
    [2480] = {n="Помощь Хинотта", d="Дождитесь, пока Серж Хинотт доделает лекарство."},
    [2521] = {n="Служба для Кум'иша", d="Если в своем путешествии по Выжженным землям вы найдете безупречную сферу из дренейского аметиста, отнесите ее Кум'ише Коллекционеру.\nБудьте внимательны - этот камень - один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренейского аметиста.\nВы будете вознаграждены за каждую безупречную сферу из дренейского аметиста, которую доставите Кум-ише.", tgo={{"Огр из клана Молота Ужаса", "Огр-маг из клана Молота Ужаса", "Громила из клана Молота Ужаса"}}},
