    [5165] = {n="Погасить Пламя Защиты", d="При помощи очищенной воды из лунного колодца загасите пламя в четырех жаровнях защиты внутри Оплота Теней в Оскверненном лесу. Затем возвращайтесь к Грете Замшелому Копыту в Изумрудное святилище.", objs={"Жаровня Боли", "Жаровня Злобы", "Жаровня Страдания", "Жаровня Ненависти"}},
    [5211] = {n="Защитники Дарроушира", d="Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.", tgo={{"Дух Дарроушира"}}},
