    [7029] = {n="Порча Злоязыкого", d="Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.\nПолейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.\nИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников.", tgo={{"Ядовитая лоза"}, {}}, objs={"Оранжевый пруд Мародона"}},
    [7044] = {n="Легенды Мародона", d="Добудьте две части скипетра Келебраса - жезл Келебраса и бриллиант Келебраса.\nНайдите способ поговорить с Келебрасом.", tgo={{"Лорд Злоязыкий"}, {"Ноксион", "Порождение Пагубника"}}},
    [7046] = {n="Скипетр Келебраса", d="Помогите Селебрасу Искупленному воссоздать скипетр Селебраса.\nПо завершении ритуала снова обратитесь к нему.", objs={"Incantation of Celebras"}},
    [7064] = {n="Яблочко от яблоньки...", d="Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах.", tgo={{"Принцесса Терадрас"}}},
    [7066] = {n="Семя Жизни", d="Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни."},
    [7067] = {n="Инструкции кентавра-парии", d="Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей."},
    [7068] = {n="Фрагменты осколка сумрака", d="Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар.", tgo={{"Темнокаменный грохотун", "Темнокаменный крушитель", "Темнокаменный рокотун"}}},
    [7201] = {n="Последняя Стихия", d="Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей.", tgo={{"Оплавленный боевой голем", "Беспощадный голем", "Создание-завоеватель"}}},
    [7441] = {n="Пузиллин и старейший Аж'Тордин", d="Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.\nЕсли добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе.", tgo={{"Пузиллин"}}},
    [7461] = {n="Древнее безумие", d="Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.\nВойдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.\nЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар.", tgo={{"Бессмер'тер"}, {"Принц Тортелдрин"}}},
    [7463] = {n="Магический напиток", d="Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.", tgo={{"Гидротварь"}}},
    [7481] = {n="Эльфийские легенды", d="Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.", objs={"Останки Тельмия Сновидца"}},
    [7489] = {n="Сеть Лефтендрис", d="Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.", tgo={{"Лефтендрис"}}},
    [7492] = {n="Лагерь Мохаче", d="Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе."},
    [7498] = {n="Гарона: Исследование уловок и предательства", d="Верните книгу законным владельцам."},
    [7499] = {n="Кодекс Обороны", d="Верните книгу законным владельцам."},
    [7500] = {n="Поваренная книга чародея", d="Верните книгу законным владельцам."},
    [7501] = {n="Свет и как его раскачать", d="Верните книгу законным владельцам."},
    [7502] = {n="Укрощая тени", d="Верните книгу законным владельцам."},
    [7503] = {n="Величайшая гонка охотников", d="Верните книгу законным владельцам."},
    [7504] = {n="Святая Болонья: О чем не говорит Свет", d="Верните книгу законным владельцам."},
